select job_name, to_char(run_time,'MM-DD HH24:MI:SS') t, status, rows_affected, details->'timing'->>'durationMs' ms, left(details->>'response', 1800) r from cron_job_audit where run_time >= '2026-11-16 09:25' and run_time < '2026-11-16 11:40' and job_name in ('/api/v1/db/update-goalie-projections-v2','ingest-projection-inputs','run-rolling-forge-pipeline','build-projection-derived-v2','run-projection-accuracy','/api/v1/db/forge-served-forecast-settle','run-projection-v2','update-shift-charts') order by run_time
